/* ══════════════════════════════════════════════════════════
   건물 여섯 채 — 캠퍼스에 세울 수 있게 모듈로 뺐습니다.
   buildings.html 은 이 모듈을 한 채씩 크게 찍어 보는 뷰어일 뿐입니다.
   opt.plate === false 면 전시용 받침판과 장식 나무 넷을 뺍니다
   (캠퍼스 위에 놓을 때는 땅이 이미 있습니다).
   ══════════════════════════════════════════════════════════ */
import * as THREE from 'three';
import { M, box, cyl, prism, win, door, archPortal, apron, column, tree, bush, plate, sign,
         steps, reveal } from './parts.js';

/* ══════════════════════════════════════════════════════════
   기린캠퍼스 건물 여섯 채 — 아이소메트릭 아이콘.
   같은 부품(parts.js)을 같은 규칙으로 쓰되 조합과 색만 다릅니다.
   나란히 놨을 때 한 캠퍼스로 읽혀야 합니다.
   ══════════════════════════════════════════════════════════ */

/* 공통 — 여섯 채가 나눠 쓰는 값. 여기가 캠퍼스의 재질입니다. */
const BASE = {
  trim: 0xFFF4DC, frame: 0xFFFFFF, glass: 0x4E8CA8, glassLit: 0x74B5CE,
  door: 0xB5713F, doorDark: 0x8E5730, doorLight: 0xD08F58,
  stone: 0xF4F1EA, stoneDark: 0xD9D4C8, gold: 0xF2B33C,
  base: 0xF0CE7E, baseDark: 0x6B4A2A, grass: 0x5FC15A, grassDark: 0x46A343,
  path: 0xF6C97E, trunk: 0x8E5A33, leaf: 0x53B84E,
};
const C = (o) => Object.assign({}, BASE, o);

/* ─────────────────────────────────────────────
   ① 본관 — 가장 격식 있는 집. 시계탑 · 기둥 현관 · 국기
   ───────────────────────────────────────────── */
/* 아이콘이 아니라 **건물**입니다.

   전 판은 폭 9.6짜리 아이소메트릭 아이콘이었고, 캠퍼스에서는 배율 1.9로
   키워 폭 18로 세웠습니다. 축이 폭 22인데 그 머리가 18이면 축을 못
   막습니다 — 뒤가 다 보입니다.

   이제 아이콘 단위 28 × 9.4, 캠퍼스 배율 3.0 → **월드 84 × 28**.
   배율만 올리지 않고 다시 그린 이유는 문 때문입니다: 그냥 3배로 키우면
   문도 3배가 되어 거인의 집이 됩니다. 층을 늘리고 창을 잘게 나눠, 커진
   것은 건물이고 문은 사람 크기에 머물게 했습니다(월드 3.5 × 4.5,
   캐릭터 키의 2.3배 — 격식 있는 정문의 비율입니다).

   구성은 실제 대학 본관이 쓰는 것입니다.
     기단      건물이 땅에서 한 단 올라섭니다
     중앙동    가장 높고, 축 정중앙에 섭니다
     좌우 별관 한 층 낮게, 뒤로 물러서서 중앙을 돋보이게 합니다
     주랑      기둥 여덟과 박공. 정면이 어디인지를 말합니다
     시계탑    멀리서 보이는 것. 축의 종점은 이것입니다
   ───────────────────────────────────────────── */
export function mainHall(g, opt = {}) {
  const P = C({ wall: 0xF6E3B4, wallLight: 0xFFF0CC, roof: 0x5B84C4, roofDark: 0x3F6BA8,
                deck: 0x8E93B8 });
  if (opt.plate !== false) plate(g, P, 34);

  const W = 28, D = 9.4;              // 전체 폭 · 안길이
  const CW = 13, CD = 9.4;            // 중앙동
  const GW = 7.2, GD = 8.4;           // 별관
  const Y = .5;                       // 기단 높이
  const H1 = 1.9, H2 = 1.75, H3 = 1.75;
  const CT = Y + H1 + H2 + H3;        // 중앙동 처마 = 5.9
  const GT = Y + H1 + H2;             // 별관 처마 = 4.15

  /* ── 기단 ── */
  box(g, W + .8, Y, D + .8, .12, M(P.stoneDark, .8), 0, Y / 2, 0);
  box(g, W + 1.5, .16, D + 1.5, .06, M(P.stone, .74), 0, .08, 0);

  /* ── 좌우 별관 ── 뒤로 .6 물러섭니다 */
  [-1, 1].forEach((sx) => {
    const gx = sx * (CW / 2 + GW / 2);
    box(g, GW, GT - Y, GD, .12, M(P.wall), gx, Y + (GT - Y) / 2, -.6);
    box(g, GW + .22, .3, GD + .22, .07, M(P.trim), gx, Y + H1, -.6);
    box(g, GW + .4, .42, GD + .4, .1, M(P.trim), gx, GT + .1, -.6);
    box(g, GW - .3, .34, GD - .3, .08, M(P.roof), gx, GT + .42, -.6);
    /* 모서리 기둥 — 덩어리에 세로선을 줍니다 */
    [-1, 1].forEach((ex) => [-1, 1].forEach((ez) =>
      box(g, .46, GT - Y, .46, .07, M(P.wallLight),
          gx + ex * (GW / 2 - .12), Y + (GT - Y) / 2, -.6 + ez * (GD / 2 - .12))));
    /* 창 두 줄 × 넷 */
    [Y + H1 * .56, Y + H1 + H2 * .52].forEach((wy) =>
      [-2.4, -.8, .8, 2.4].forEach((wx) => {
        win(g, P, gx + wx, wy, GD / 2 - .6 + .02, 0, .74, 1.05);
        win(g, P, gx + wx, wy, -GD / 2 - .6 - .02, Math.PI, .74, 1.05);
      }));
    [-2.2, 0, 2.2].forEach((wz) => [Y + H1 * .56, Y + H1 + H2 * .52].forEach((wy) => {
      win(g, P, gx + sx * (GW / 2 + .02), wy, wz - .6, sx * Math.PI / 2, .74, 1.05);
    }));
  });

  /* ── 중앙동 ── */
  box(g, CW, CT - Y, CD, .12, M(P.wall), 0, Y + (CT - Y) / 2, 0);
  box(g, CW + .24, .3, CD + .24, .07, M(P.trim), 0, Y + H1, 0);
  box(g, CW + .24, .26, CD + .24, .07, M(P.trim), 0, Y + H1 + H2, 0);
  box(g, CW + .55, .5, CD + .55, .12, M(P.trim), 0, CT + .12, 0);
  box(g, CW - .3, .4, CD - .3, .1, M(P.roof), 0, CT + .46, 0);
  [-1, 1].forEach((ex) => [-1, 1].forEach((ez) =>
    box(g, .52, CT - Y, .52, .07, M(P.wallLight),
        ex * (CW / 2 - .12), Y + (CT - Y) / 2, ez * (CD / 2 - .12))));

  /* 창 — 주랑이 가운데 아래를 가리므로 1층은 바깥 두 짝만 */
  const yA = Y + H1 * .56, yB = Y + H1 + H2 * .52, yC = Y + H1 + H2 + H3 * .5;
  [-5.4, -3.9, 3.9, 5.4].forEach((wx) => win(g, P, wx, yA, CD / 2 + .02, 0, .8, 1.1));
  [-5.4, -3.9, -2.4, -.9, .9, 2.4, 3.9, 5.4].forEach((wx) => {
    win(g, P, wx, yB, CD / 2 + .02, 0, .8, 1.1);
    win(g, P, wx, yC, CD / 2 + .02, 0, .8, .95);
    win(g, P, wx, yB, -CD / 2 - .02, Math.PI, .8, 1.1);
  });
  [-2.6, 0, 2.6].forEach((wz) => [yA, yB, yC].forEach((wy) => {
    win(g, P, CW / 2 + .02, wy, wz, Math.PI / 2, .8, 1.05);
    win(g, P, -CW / 2 - .02, wy, wz, -Math.PI / 2, .8, 1.05);
  }));

  /* ── 주랑 — 기둥 여덟 · 박공 ── */
  const PZ = CD / 2 + 1.7, COL = 4.5;
  box(g, 12.2, .34, 3.0, .08, M(P.stone, .76), 0, Y - .05, PZ - .2);   // 주랑 바닥
  /* 세 문 앞 네 기둥을 비웁니다. */
  [-5.25, -3.75, 3.75, 5.25].forEach((x) =>
    column(g, P, x, Y + .12, PZ, COL, .34));
  box(g, 12.0, .55, 2.7, .1, M(P.trim), 0, Y + .23 + COL + .4, PZ - .1);
  box(g, 12.4, .22, 2.9, .06, M(P.trim), 0, Y + .23 + COL + .78, PZ - .1);
  prism(g, 12.4, 1.7, 2.9, M(P.roof, .6), 0, Y + .23 + COL + .89, PZ - .12, .1);
  prism(g, 11.2, 1.15, .26, M(P.trim, .55), 0, Y + .23 + COL + 1.02, PZ + 1.36, .06);

  /* ── 문 셋 ──
     벽이 아니라 **감실 안**에 앉습니다. 문설주가 좌우와 위를 감싸고,
     그 뒤 어두운 판이 깊이를 만듭니다. 문 자체는 사람 크기 그대로. */
  /* 아치를 뺐습니다. 문설주(사각)와 아치(반원)를 같은 문에 겹쳐 씌우니
     테두리가 둘이 되어 서로를 잘랐습니다. 그리스식 주랑 아래에 로마식
     아치를 놓은 셈이라 문법도 섞였습니다 — 주랑 밑은 **평인방**입니다.
     아치는 도서관 로지아 하나에만 둡니다. */
  [-2.4, 0, 2.4].forEach((x, i) => {
    reveal(g, P, x, Y, CD / 2 + .06, 1.15, 1.62, .42);
    door(g, P, x, Y + .78, CD / 2 + .18, 1.15, 1.5);
    /* 문 위 — 가운데만 작은 박공, 좌우는 평평한 갓. 실제 신고전 현관이
       가운데를 한 번 높여 어디가 주된 문인지를 말하는 방식입니다. */
    box(g, 2.15, .2, .6, .04, M(P.trim, .52), x, Y + 2.06, CD / 2 + .22);
    if (i === 1) prism(g, 2.4, .66, .6, M(P.trim, .5), x, Y + 2.16, CD / 2 + .22, .05);
    else box(g, 1.85, .17, .52, .04, M(P.stone, .62), x, Y + 2.24, CD / 2 + .22);
  });

  /* ── 계단 ── 주랑 폭 전체. 기단 높이만큼 올라섭니다 */
  steps(g, P, 0, PZ + 1.34, 12.4, Y + .12, 1.55, 3);

  /* ── 시계탑 ── 축의 종점. 멀리서 보이는 것은 결국 이것입니다 */
  const TW = 3.4, T0 = CT + .66;
  box(g, TW, 3.5, TW, .12, M(P.wall), 0, T0 + 1.75, 0);
  box(g, TW + .3, .28, TW + .3, .07, M(P.trim), 0, T0 + 1.2, 0);
  box(g, TW + .42, .34, TW + .42, .08, M(P.trim), 0, T0 + 3.5, 0);
  [-1, 1].forEach((ex) => [-1, 1].forEach((ez) =>
    box(g, .4, 3.5, .4, .06, M(P.wallLight), ex * (TW / 2 - .1), T0 + 1.75, ez * (TW / 2 - .1))));
  /* 시계 — 네 면 중 정면과 좌우 */
  [[0, TW / 2 + .04, 0], [TW / 2 + .04, 0, Math.PI / 2], [-TW / 2 - .04, 0, -Math.PI / 2]]
    .forEach(([cx, cz, ry]) => {
      const f = new THREE.Group(); f.position.set(cx, T0 + 2.5, cz); f.rotation.y = ry; g.add(f);
      cyl(f, 1.02, 1.02, .14, 28, M(P.trim, .5), 0, 0, 0).rotation.x = Math.PI / 2;
      cyl(f, .84, .84, .16, 28, M(0x3E6E82, .4), 0, 0, .04).rotation.x = Math.PI / 2;
      box(f, .1, .56, .18, .03, M(P.trim, .4), 0, .2, .1);
      box(f, .44, .1, .18, .03, M(P.trim, .4), .16, 0, .1);
    });
  /* 종루 — 아치 트인 층 */
  const B0 = T0 + 3.84, BW = 2.8;
  box(g, BW, 1.5, BW, .1, M(P.wallLight), 0, B0 + .75, 0);
  [[0, BW / 2 + .02, 0], [0, -BW / 2 - .02, Math.PI], [BW / 2 + .02, 0, Math.PI / 2],
   [-BW / 2 - .02, 0, -Math.PI / 2]].forEach(([bx2, bz, ry]) =>
    win(g, P, bx2, B0 + .78, bz, ry, .9, 1.0, 'arch'));
  box(g, BW + .5, .3, BW + .5, .08, M(P.trim), 0, B0 + 1.6, 0);
  /* 첨탑 */
  prism(g, 3.0, 2.4, 3.0, M(P.roofDark, .5), 0, B0 + 1.72, 0, .06);
  cyl(g, .06, .06, .9, 8, M(P.gold, .3), 0, B0 + 4.4, 0);
  { const b = new THREE.Mesh(new THREE.SphereGeometry(.26, 14, 10), M(P.gold, .3));
    b.position.set(0, B0 + 4.0, 0); b.castShadow = true; g.add(b); }

  /* ── 뒷면 ──
     뒤와 옆이 똑같은 창 격자뿐이라 벽지처럼 보였습니다. 대학 본관의
     뒤에는 반드시 있는 것 — 후문과 계단, 비상계단, 설비 — 을 둡니다.
     부품이 +z 를 보고 만들어져 있어 돌린 그룹 안에서 앞면 좌표로 씁니다. */
  { const b = new THREE.Group(); b.rotation.y = Math.PI; g.add(b);
    reveal(b, P, 0, Y, CD / 2 + .06, 1.3, 1.7, .40);
    door(b, P, 0, Y + .84, CD / 2 + .18, 1.3, 1.6);
    box(b, 3.2, .26, .9, .05, M(P.trim, .52), 0, Y + 2.20, CD / 2 + .24);
    steps(b, P, 0, CD / 2 + .58, 3.6, Y + .12, 1.0, 2);
    /* 비상계단 — 별관 뒤 한 쪽. 실루엣이 단조로운 면을 끊습니다 */
    const ex = -(CW / 2 + GW / 2) + 2.6;
    box(b, .22, GT - Y, 1.5, .04, M(P.trim, .5), ex, Y + (GT - Y) / 2, GD / 2 + .6 + .75);
    box(b, 2.4, .18, .22, .04, M(P.trim, .5), ex + 1.1, Y + H1, GD / 2 + .6 + 1.42);
    [0, 1, 2, 3, 4].forEach((i) =>
      box(b, 2.2, .1, .34, .03, M(P.stoneDark, .7), ex + 1.1,
          Y + .3 + i * (H1 - .3) / 4, GD / 2 + .6 + 1.42 - i * .18));
  }

  /* ── 지붕 설비 ──
     세 덩어리 다 평평한 파랑 판 하나였습니다. 항공 시점에서 가장 크게
     잡히는 면이라, 여기가 비면 건물이 아니라 색종이입니다. */
  [-1, 1].forEach((sx) => {
    const gx = sx * (CW / 2 + GW / 2);
    box(g, 2.2, .55, 1.6, .08, M(P.trim, .62), gx + sx * 1.4, GT + .70, -.6 - 1.9);
    cyl(g, .42, .42, .70, 12, M(P.wallLight, .5), gx - sx * 1.6, GT + .78, -.6 + 1.8);
  });
  box(g, 2.6, .5, 1.4, .08, M(P.trim, .62), -3.6, CT + .70, -2.5);
  box(g, 2.6, .5, 1.4, .08, M(P.trim, .62), 3.6, CT + .70, -2.5);

  /* ── 깃대 — 별관 옥상 ── */
  box(g, .8, .3, .8, .07, M(P.trim, .6), -10.1, GT + .6, 1.6);
  cyl(g, .07, .07, 3.4, 10, M(0xD8DCE2, .35), -10.1, GT + 2.4, 1.6);
  {
    const sh = new THREE.Shape();
    sh.moveTo(0, 0); sh.lineTo(1.7, -.34); sh.lineTo(1.7, .56); sh.lineTo(0, .9); sh.closePath();
    const ge = new THREE.ExtrudeGeometry(sh, { depth: .1, bevelEnabled: true, bevelSize: .04,
      bevelThickness: .04, bevelSegments: 2, steps: 1 });
    const m = new THREE.Mesh(ge, M(0xE8483C, .62));
    m.position.set(-10.05, GT + 3.1, 1.56); m.castShadow = true; g.add(m);
  }
  sign(g, '본관', 0, Y + .23 + COL + .78, PZ + 1.5, 4.4, .8, '#3F6BA8', '#FFFFFF');
}

/* ─────────────────────────────────────────────
   ② 도서관/* ─────────────────────────────────────────────
   ② 도서관 — 돔과 아치창. 여섯 중 가장 조용해 보여야 합니다
   ───────────────────────────────────────────── */
/* 도서관은 **키 큰 아치창이 줄지어 선 것**으로 읽힙니다.

   실제 대학 중앙도서관의 정면은 거의 예외 없이 같은 문법입니다: 묵직한
   1층 기단 위로 두 층을 관통하는 좁고 높은 아치창이 반복되고, 그 위를
   두꺼운 처마가 한 줄로 닫습니다. 창 하나가 두 층을 먹기 때문에 안이
   열람실이라는 것이 밖에서 보입니다 — 사무실이면 층마다 창이 갈립니다.

   아이콘 단위 15 × 10, 배율 3.0 → **월드 45 × 30**.
   ───────────────────────────────────────────── */
export function library(g, opt = {}) {
  const P = C({ wall: 0xF3EBDA, wallLight: 0xFDF7EA, roof: 0x3FB3A2, roofDark: 0x2C8C7E });
  if (opt.plate !== false) plate(g, P, 20);

  const W = 15, D = 10, Y = .4;
  /* 1층을 2.3 에서 3.6 으로 올립니다.

     아치 하나의 머리는 문 위 1.67 에서 솟아 반지름 1.27 을 더한 3.36
     높이에서 끝나는데, 1층 처마가 2.7 에 있었습니다. 처마가 아치 이마를
     가로질러 **반원이 잘린 토막**으로 보였습니다. 층을 올려 아치를 층
     안에 넣습니다 — 실제로도 로지아를 낸 층은 다른 층보다 높습니다. */
  const BH = 3.6;                       // 1층 — 로지아가 사는 층
  const MH = 4.3;                       // 열람실 층
  const TOP = Y + BH + MH;              // 처마 = 7.0

  box(g, W + .7, Y, D + .7, .1, M(P.stoneDark, .8), 0, Y / 2, 0);

  /* ── 1층 기단 — 묵직하게. 작은 네모창만 ── */
  box(g, W, BH, D, .12, M(P.stoneDark, .8), 0, Y + BH / 2, 0);
  box(g, W + .3, .26, D + .3, .07, M(P.trim), 0, Y + BH, 0);
  /* 로지아가 폭 10.6 을 먹으므로 기단 창은 그 바깥에만 남습니다 */
  [-6.6, 6.6].forEach((x) => win(g, P, x, Y + BH * .3, D / 2 + .02, 0, .6, .8));
  [-3.4, 0, 3.4].forEach((z) => [-1, 1].forEach((sx) =>
    win(g, P, sx * (W / 2 + .02), Y + BH * .55, z, sx * Math.PI / 2, .55, .7)));

  /* ── 현관 — 아치 셋의 로지아 ──
     전 판은 문 **앞에** 벽 판을 한 장 더 세워 놓았습니다(z = D/2 - .1,
     두께 .5 → 문과 아치를 통째로 덮었습니다). 그래서 아치가 안 보이고
     문만 벽에 붙은 것처럼 보였습니다. 그 판을 뒤로 물려 감실 벽으로
     쓰고, 문과 아치를 그 앞에 세웁니다. */
  /* 아치 셋을 1.7 간격에 놓았더니 서로를 물었습니다 — 아치 하나가
     지름 2.54 를 먹는데 간격이 1.7 이면 이웃의 반원 안으로 들어갑니다.
     2.9 로 벌리고 감실도 그만큼 넓힙니다. 문설주(reveal)는 뺐습니다:
     아치가 이미 테두리라 둘을 겹치면 테가 둘이 됩니다. */
  /* 문과 아치를 벽면 **바깥**으로 냅니다.
     전 판은 z = D/2 - .2 에 두었는데, 기단 덩어리의 앞면이 z = D/2 라
     문이 벽 속에 파묻혀 문짝 윗동강과 손잡이만 보였습니다. 안으로
     파고 싶었지만 불리언이 없으니, 아치를 벽에 **덧대는** 쪽이 맞습니다 —
     실제 도서관 정면도 대개 아케이드를 앞에 붙입니다. */
  [-2.9, 0, 2.9].forEach((x) => {
    door(g, P, x, Y + .82, D / 2 + .1, 1.1, 1.55);
    archPortal(g, P, x, Y + .02, D / 2 + .1, 1.1, 1.55);
  });
  /* 아케이드 양끝 벽기둥 — 셋을 한 덩어리로 묶습니다 */
  [-1, 1].forEach((s) => box(g, .66, BH + .34, .78, .06, M(P.wallLight),
                             s * 5.5, Y + (BH + .34) / 2, D / 2 + .16));
  /* 아케이드 위 프리즈 — 여기가 이름을 다는 자리입니다. 0.52 였을 때는
     띠일 뿐이었고, 간판을 벽면(z = D/2 + .04)에 붙였더니 이 띠(앞면이
     z = D/2 + .62)에 **통째로 묻혔습니다.** 문 앞에서 올려다보면 글자는
     하나도 안 보이고 청록 막대의 윗동강만 보였습니다. 띠를 이름이 들어갈
     만큼 키우고, 간판을 그 앞면에 붙입니다. 위로는 열람실 아치창 밑
     (Y + BH + 4.61)까지 여유가 있습니다. */
  box(g, 12.0, .68, .92, .06, M(P.trim, .55), 0, Y + BH + .24, D / 2 + .16);

  /* ── 계단 ── */
  steps(g, P, 0, D / 2 + .42, 11.0, Y + .1, 1.4, 3);

  /* ── 열람실 — 두 층을 관통하는 아치창 일곱 ── */
  box(g, W - 1.4, MH, D - .6, .12, M(P.wall), 0, Y + BH + MH / 2, 0);
  const AX = [-4.2, -2.8, -1.4, 0, 1.4, 2.8, 4.2];
  AX.forEach((x) => {
    win(g, P, x, Y + BH + MH * .48, (D - .6) / 2 + .02, 0, .82, 2.9, 'arch');
    win(g, P, x, Y + BH + MH * .48, -(D - .6) / 2 - .02, Math.PI, .82, 2.9, 'arch');
  });
  /* 창 사이 필라스터 — 벽이 아니라 기둥 사이가 창이라는 인상을 만듭니다 */
  [-4.9, -3.5, -2.1, -.7, .7, 2.1, 3.5, 4.9].forEach((x) =>
    box(g, .34, MH, .3, .05, M(P.wallLight), x, Y + BH + MH / 2, (D - .6) / 2 + .06));
  [-3.0, 0, 3.0].forEach((z) => [-1, 1].forEach((sx) =>
    win(g, P, sx * ((W - 1.4) / 2 + .02), Y + BH + MH * .48, z, sx * Math.PI / 2, .78, 2.7, 'arch')));

  /* ── 처마 · 난간 ── */
  box(g, W + .5, .42, D + .1, .1, M(P.trim), 0, TOP + .1, 0);
  box(g, W + .1, .55, D - .3, .08, M(P.wallLight), 0, TOP + .58, 0);
  for (let i = -6; i <= 6; i++)
    box(g, .2, .5, .2, .04, M(P.trim, .5), i * 1.1, TOP + .58, (D - .3) / 2 + .02);

  /* ── 돔 ── 조용한 집의 표식 */
  const DY = TOP + .9;
  cyl(g, 2.5, 2.7, 1.0, 30, M(P.wallLight, .5), 0, DY + .5, 0);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    win(g, P, Math.sin(a) * 2.52, DY + .52, Math.cos(a) * 2.52, a, .5, .6, 'arch');
  }
  box(g, 5.8, .24, 5.8, .1, M(P.trim), 0, DY + 1.08, 0);
  { const dm = new THREE.Mesh(new THREE.SphereGeometry(2.5, 26, 14, 0, Math.PI * 2, 0, Math.PI / 2),
                              M(P.roof, .3));
    dm.position.set(0, DY + 1.16, 0); dm.scale.y = .74; dm.castShadow = true; g.add(dm); }
  cyl(g, .09, .09, 1.1, 8, M(P.gold, .3), 0, DY + 3.4, 0);
  { const b = new THREE.Mesh(new THREE.SphereGeometry(.3, 14, 10), M(P.gold, .3));
    b.position.set(0, DY + 2.9, 0); b.castShadow = true; g.add(b); }

  /* ── 좌우 끝 파빌리온 ── 앞으로 나와 정면을 잡아 줍니다 */
  [-1, 1].forEach((sx) => {
    const px = sx * 6.2, PH = Y + BH + 2.4;
    box(g, 2.6, PH - Y, D + 1.1, .12, M(P.wall), px, Y + (PH - Y) / 2, 0);
    box(g, 2.9, .34, D + 1.4, .08, M(P.trim), px, PH + .06, 0);
    prism(g, 2.9, 1.1, D + 1.4, M(P.roof, .5), px, PH + .2, 0, .08);
    win(g, P, px, Y + BH + 1.0, (D + 1.1) / 2 + .02, 0, .95, 1.7, 'arch');
    win(g, P, px, Y + BH + 1.0, -(D + 1.1) / 2 - .02, Math.PI, .95, 1.7, 'arch');
    [-2.6, 0, 2.6].forEach((z) =>
      win(g, P, px + sx * 1.32, Y + BH + 1.0, z, sx * Math.PI / 2, .8, 1.5, 'arch'));
  });

  /* 간판은 프리즈 **앞면**에 붙입니다(z = D/2 + .62 가 그 면). 벽면에
     붙이면 프리즈 안에 묻혀 글자가 안 보입니다 — 그게 문 앞에서
     "간판이 빈 청록 막대" 로 보이던 이유입니다. */
  sign(g, '도서관', 0, Y + BH + .24, D / 2 + .50, 5.0, .52, '#2C8C7E', '#FFFFFF');

  /* ── 뒷면 ──
     기단 뒤는 작은 창 셋이 전부라 위층 아치창 일곱과 리듬이 안 맞았고,
     서고를 쓰는 건물인데 **짐 들이는 문이 없었습니다.** 캠퍼스를 한
     바퀴 도는 순간 앞만 만든 티가 나는 자리입니다.

     부품(door·reveal·steps)이 전부 +z 를 보고 만들어져 있어서 돌린
     그룹 안에 넣습니다 — 좌표는 그 안에서 전부 앞면 기준입니다. */
  { const b = new THREE.Group(); b.rotation.y = Math.PI; g.add(b);
    [-6.6, -3.4, 3.4, 6.6].forEach((x) => win(b, P, x, Y + BH * .42, D / 2 + .02, 0, .8, 1.1));
    door(b, P, 0, Y + .82, D / 2 + .10, 1.3, 1.6);
    reveal(b, P, 0, Y + .02, D / 2 + .10, 1.3, 1.6);
    steps(b, P, 0, D / 2 + .42, 3.2, Y + .1, .9, 2);
    /* 하역대 — 서고 뒤에는 반드시 이것이 있습니다 */
    box(b, 4.0, .34, 1.4, .06, M(P.stoneDark, .8), 3.8, .17, D / 2 + .80);
    [-1, 1].forEach((s) => cyl(b, .1, .1, .9, 8, M(P.trim, .5), 3.8 + s * 1.8, .62, D / 2 + .32));
  }

  /* ── 지붕 ──
     큰 흰 평면 하나에 회색 사각형만 있었습니다. 영상에서 가장 오래
     잡히는 면인데 아무것도 없으면 건물이 종이 모형이 됩니다.
     채광창 둘과 설비 둘 — 돔 받침(±2.9)은 비켜 갑니다. */
  [-1, 1].forEach((s) => {
    box(g, 3.0, .30, 1.5, .06, M(P.trim, .6), s * 4.9, TOP + .40, 2.2);
    box(g, 2.6, .16, 1.15, .05,
        M(P.glass, .2, { transparent: true, opacity: .78 }), s * 4.9, TOP + .58, 2.2);
  });
  box(g, 1.5, .70, 1.2, .08, M(P.stoneDark, .7), -5.2, TOP + .60, -2.6);
  cyl(g, .34, .34, .8, 12, M(P.trim, .5), 4.8, TOP + .65, -2.8);
}

/* ─────────────────────────────────────────────
   ③ 기숙사/* ─────────────────────────────────────────────
   ③ 기숙사 — 사는 집. 발코니 · 굴뚝 · 옥상 데크
   ───────────────────────────────────────────── */
export function dorm(g, opt = {}) {
  const P = C({ wall: 0xFFE7C6, wallLight: 0xFFF3E2, roof: 0xF2934F, roofDark: 0xD1762F,
                /* 데크는 나무입니다. 초록이면 위에서 볼 때 잔디가 지붕에
                   올라간 것으로 읽힙니다 — 데크는 밟는 바닥이지 정원이 아닙니다. */
                deck: 0xC49A6C });
  if (opt.plate !== false) {
    plate(g, P, 14.4);
    [[-5.4, 4.4, .9], [5.4, 4.4, .9], [-5.6, -4.0, 1.05], [5.6, -4.0, 1.05]]
      .forEach(([x, z, s]) => tree(g, P, x, z, s));
  }
  bush(g, P, -3.4, 5.0, 1); bush(g, P, 3.4, 5.0, 1);
  const W = 8.2, D = 5.4, H1 = 2.7, H2 = 2.5, Y = .12;
  box(g, W, H1, D, .12, M(P.wall), 0, Y + H1 / 2, 0);
  box(g, W + .18, .3, D + .18, .08, M(P.trim), 0, Y + H1, 0);
  box(g, W, H2, D, .12, M(P.wall), 0, Y + H1 + .3 + H2 / 2, 0);
  box(g, W + .3, .4, D + .3, .1, M(P.trim), 0, Y + H1 + .3 + H2 + .13, 0);
  const yLo = Y + H1 * .56, yHi = Y + H1 + .3 + H2 * .5;
  /* 창이 많고 작습니다 — 방이 여럿이라는 뜻입니다.

     뒷면 1층에는 창이 아예 없었습니다. 아이콘으로 한 채만 볼 때는 안
     드러나는데, 캐릭터가 걸어서 뒤로 돌면 통짜 벽 하나가 나옵니다.
     사는 집은 사방에 방이 있습니다 — 뒤도 채웁니다.

     불 켜진 창을 섞습니다. 기숙사만 가진 신호라 멀리서도 "저기는 사람이
     산다" 로 읽힙니다. 규칙적으로 켜면 조명이 되고 불규칙해야 사람이
     됩니다 — 앞뒤로 다른 칸을 켭니다. */
  const LIT_FRONT = new Set([-1.45, 2.9]);
  const LIT_BACK = new Set([-2.9, 1.45]);
  [-2.9, -1.45, 1.45, 2.9].forEach((x) => {
    if (Math.abs(x) > 1.2) win(g, P, x, yLo, D / 2 + .02, 0, .92, 1.25);
    win(g, P, x, yHi, D / 2 + .02, 0, .92, 1.25);
    win(g, P, x, yHi, -D / 2 - .02, Math.PI, .92, 1.25);
    win(g, P, x, yLo, -D / 2 - .02, Math.PI, .92, 1.25);
    /* 불빛은 **따뜻한 색**입니다. 유리색(청록)으로 켜면 옆 창과 구분이 안 되고,
       구분돼도 "조명이 켜졌다" 지 "사람이 있다" 로는 안 읽힙니다. */
    const lit = () => M(0xFFD98A, .3, { emissive: 0xFFC65C, emissiveIntensity: .85 });
    if (LIT_FRONT.has(x)) box(g, .70, 1.02, .05, .02, lit(), x, yHi, D / 2 + .06);
    if (LIT_BACK.has(x)) box(g, .70, 1.02, .05, .02, lit(), x, yHi, -D / 2 - .06);
  });
  [-1.4, 1.4].forEach((z) => {
    win(g, P, W / 2 + .02, yLo, z, Math.PI / 2, .92, 1.25);
    win(g, P, W / 2 + .02, yHi, z, Math.PI / 2, .92, 1.25);
    win(g, P, -W / 2 - .02, yLo, z, -Math.PI / 2, .92, 1.25);
    win(g, P, -W / 2 - .02, yHi, z, -Math.PI / 2, .92, 1.25);
  });
  /* 발코니 — 위층 창 아래 난간.
     앞면 둘뿐이었습니다. 그러면 정문 쪽만 사람이 사는 집이 됩니다.
     뒤에도 답니다 — 한 채에 방이 여럿이라는 말을 사방에서 합니다. */
  const balcony = (x, z, face) => {
    const s = face;                                   // +1 앞, -1 뒤
    box(g, 1.6, .16, .8, .06, M(P.trim), x, yHi - .78, z + s * .38);
    box(g, 1.6, .5, .1, .04, M(P.wallLight), x, yHi - .52, z + s * .74);
    [-.6, 0, .6].forEach((dx) =>
      box(g, .08, .46, .1, .03, M(P.trim, .5), x + dx, yHi - .54, z + s * .74));
  };
  [-2.9, 2.9].forEach((x) => balcony(x, D / 2, 1));
  balcony(-1.45, -D / 2, -1);                         // 뒤는 하나만 — 앞이 얼굴입니다
  door(g, P, 0, Y + 1.2, D / 2 + .12, 1.9, 2.3);
  archPortal(g, P, 0, Y + 1.2 - (2.3) / 2, D / 2 + .12, 1.9, 2.3);
  box(g, 3.0, .2, 1.5, .07, M(P.roof, .6), 0, Y + 2.6, D / 2 + .7);   // 문 위 차양
  apron(g, P, 0, 0, D / 2 + 1.1, 4.2);
  const yT = Y + H1 + .3 + H2 + .34;
  box(g, W + .48, .5, D + .48, .12, M(P.roof), 0, yT, 0);
  box(g, W - .1, .34, D - .1, .1, M(P.roofDark, .7), 0, yT + .3, 0);
  /* 옥상 데크 — 사는 집이라 옥상에 쓸 일이 있습니다.
     초록이던 것을 나무색으로 바꿉니다. 잔디와 같은 계열이라 위에서 보면
     지붕에 잔디가 올라간 것으로 읽혔습니다 — 데크는 사람이 밟는 바닥이지
     정원이 아닙니다. */
  box(g, 3.6, .22, 3.0, .12, M(P.deck, .8), -1.8, yT + .48, .2);
  [-3.2, -.4].forEach((x) => box(g, .12, .62, 3.0, .05, M(P.trim, .55), x, yT + .78, .2));
  /* 널빤지 결 — 나무라는 것을 한 번 더 말합니다 */
  [-3.0, -2.4, -1.8, -1.2, -.6].forEach((x) =>
    box(g, .06, .02, 2.9, .01, M(0x9A6B3F, .85), x, yT + .60, .2));
  /* 빨래 한 줄 — 옥상에 사람이 올라온다는 증거. 위에서 내려다보는 각도에
     이것 하나가 있고 없고가 큽니다.
     기둥 둘을 세우고 그 사이에 줄을 눕힙니다 — 눕히려면 z 로 90도 돌려야
     합니다(실린더의 기본 축은 Y 입니다). */
  const POST = yT + .59, POST_H = 1.0;
  [-3.0, -.6].forEach((x) => cyl(g, .05, .05, POST_H, 6, M(P.trim, .6), x, POST + POST_H / 2, .2));
  const line = cyl(g, .025, .025, 2.4, 5, M(0xE8E2D4, .8), -1.8, POST + POST_H - .1, .2);
  line.rotation.z = Math.PI / 2;
  [[0xF2B6C6, -2.6, .40], [0xBBD9F2, -1.8, .48], [0xFFE7A8, -1.0, .36]].forEach(([c, x, h]) => {
    const t = box(g, .42, h, .03, .02, M(c, .88), x, POST + POST_H - .12 - h / 2, .2);
    t.rotation.z = .04;
  });
  /* 굴뚝 — 모서리로 옮깁니다. 가운데도 모서리도 아닌 자리에 있으면
     실수로 놓인 것처럼 보입니다. */
  box(g, .9, 1.6, .9, .1, M(0xD98F5C, .8), 3.1, yT + 1.0, -1.8);
  box(g, 1.1, .26, 1.1, .06, M(P.trim, .7), 3.1, yT + 1.86, -1.8);
  sign(g, '기숙사', 0, yT + .06, D / 2 + .42, 2.9, .88, '#D1762F', '#FFFFFF');
}

/* ─────────────────────────────────────────────
   ④ 학생회관 — 볼일 보는 곳. 넓은 유리 정면 · 차양 · 게시판
   ───────────────────────────────────────────── */
/* 본관·도서관과 **같은 크기, 다른 성격**.

   앞의 둘이 격식(대칭 · 돌 · 아치)이라면 여기는 생활입니다: 1층이 통째로
   유리이고 긴 차양이 앞으로 나오며, 위층은 가로로 길게 띠창이 돕니다.
   한쪽 끝에는 둥근 유리 탑이 붙어 멀리서도 "저기가 학생회관" 이 됩니다.
   광장 세 변 중 하나를 맡으므로 크기는 같아야 하고, 성격은 달라야
   광장이 한 건물의 반복으로 보이지 않습니다.

   아이콘 단위 14 × 9.4, 배율 3.0 → **월드 42 × 28**.
   ───────────────────────────────────────────── */
export function union(g, opt = {}) {
  const P = C({ wall: 0xF2F6F0, wallLight: 0xFFFFFF, roof: 0x63C47C, roofDark: 0x43A05C,
                deck: 0xBFD8C6 });
  if (opt.plate !== false) plate(g, P, 19);

  const W = 14, D = 9.4, Y = .35;
  const G = 2.1, U = 3.3;               // 1층 · 위 두 층
  const TOP = Y + G + U;                // 처마 = 5.75

  box(g, W + .7, Y, D + .7, .1, M(P.stoneDark, .8), 0, Y / 2, 0);

  /* ── 1층 — 통유리 ── */
  box(g, W - .5, G, D - .3, .1, M(P.glass, .16), 0, Y + G / 2, 0);
  box(g, W - .3, .22, D - .1, .06, M(P.trim), 0, Y + .06, 0);
  box(g, W - .3, .3, D - .1, .07, M(P.trim), 0, Y + G, 0);
  /* 유리 사이 기둥 — 통유리는 기둥이 있어야 유리로 보입니다 */
  [-6.2, -4.4, -2.6, 2.6, 4.4, 6.2].forEach((x) =>
    box(g, .3, G, .34, .05, M(P.wallLight), x, Y + G / 2, (D - .3) / 2 + .04));
  [-1, 1].forEach((sx) => [-3.2, -1.0, 1.0, 3.2].forEach((z) =>
    box(g, .34, G, .3, .05, M(P.wallLight), sx * ((W - .5) / 2 + .04), Y + G / 2, z)));

  /* ── 문 — 넓은 유리문 ──
     여기는 격식이 아니라 생활이라 아치를 안 씁니다. 대신 두꺼운
     금속 테를 두르고 문 위를 한 줄 띄워, 통유리 가운데 어디가 문인지를
     테두리만으로 말합니다. */
  /* 나무문을 뺐습니다 — 통유리 건물에 참나무 두 짝은 다른 건물의
     부품입니다. 유리 두 짝에 금속 세로바를 대고, 위에 상인방 하나. */
  const GZ = (D - .3) / 2 + .04;
  box(g, 2.9, 1.8, .3, .04, M(P.stoneDark, .86), 0, Y + .8, GZ - .16);   // 안쪽 어둠
  [-1, 1].forEach((s) => {
    box(g, .92, 1.56, .14, .03, M(P.glassLit, .16), s * .5, Y + .82, GZ + .1);
    box(g, .06, 1.5, .17, .02, M(P.trim, .45), s * .96, Y + .82, GZ + .13);
    cyl(g, .05, .05, .5, 8, M(P.trim, .4), s * .14, Y + .82, GZ + .16);  // 손잡이 봉
  });
  box(g, .12, 1.62, .18, .03, M(P.trim, .5), 0, Y + .82, GZ + .13);      // 가운데 선틀
  [-1, 1].forEach((s) => box(g, .22, 1.9, .3, .04, M(P.wallLight), s * 1.55, Y + .9, GZ + .04));
  box(g, 3.5, .3, .42, .05, M(P.trim, .5), 0, Y + 1.82, GZ + .08);       // 상인방 하나만
  /* 문 앞 두 단 — 1층이 낮아 세 단은 과합니다 */
  steps(g, P, 0, (D - .3) / 2 + .34, 6.0, Y + .08, 1.1, 2);

  /* ── 차양 — 앞으로 길게 ── */
  const CZ = (D - .3) / 2 + 1.5;
  box(g, W + .8, .26, 3.1, .08, M(P.roof, .6), 0, Y + G + .5, CZ);
  box(g, W + .4, .12, 2.7, .05, M(P.wallLight), 0, Y + G + .34, CZ);
  [-5.6, -1.9, 1.9, 5.6].forEach((x) =>
    cyl(g, .12, .13, G + .32, 10, M(P.trim, .5), x, Y + (G + .32) / 2, CZ + 1.2));

  /* ── 위 두 층 — 가로 띠창 ── */
  box(g, W - 1.0, U, D - .8, .12, M(P.wall), 0, Y + G + U / 2, 0);
  box(g, W - .7, .26, D - .5, .07, M(P.trim), 0, Y + G + U * .5, 0);
  [Y + G + U * .26, Y + G + U * .76].forEach((wy) => {
    [-4.6, -2.3, 0, 2.3, 4.6].forEach((x) => {
      win(g, P, x, wy, (D - .8) / 2 + .02, 0, 2.0, .85);
      win(g, P, x, wy, -(D - .8) / 2 - .02, Math.PI, 2.0, .85);
    });
    [-2.6, 0, 2.6].forEach((z) => [-1, 1].forEach((sx) =>
      win(g, P, sx * ((W - 1.0) / 2 + .02), wy, z, sx * Math.PI / 2, 1.9, .85)));
  });

  /* ── 옥상 — 난간과 퍼걸러 ── */
  box(g, W - .6, .5, D - .4, .1, M(P.trim), 0, TOP + .16, 0);
  box(g, W - 1.0, .34, D - .8, .08, M(P.deck, .7), 0, TOP + .1, 0);
  [-1, 1].forEach((sx) => box(g, .22, .5, D - 2.4, .05, M(P.trim, .5),
                              sx * 3.6, TOP + .68, -.4));
  /* ── 둥근 유리 탑 ── 멀리서 보이는 표식 */
  const RX = 5.4, RZ = -1.2, RR = 2.15;
  /* 지붕 살은 **탑 발치를 비켜 갑니다.** 전 판은 x 0.3~6.9 에 열셋을
     쭉 깔았는데, 탑이 x 3.05~7.75 를 차지하므로 살 여섯이 초록 돔을
     그대로 관통했습니다 — 어느 각도에서 봐도 돔이 빗에 꿰여 있었습니다. */
  for (let i = -6; i <= 6; i++) {
    const fx = 3.6 + i * .55;
    if (Math.hypot(fx - RX, -.4 - RZ) < RR + .5) continue;
    box(g, .16, .12, D - 2.2, .04, M(P.wallLight), fx, TOP + .92, -.4);
  }
  cyl(g, RR, RR + .1, TOP - Y + .5, 26, M(P.glass, .16), RX, Y + (TOP - Y + .5) / 2, RZ);
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    box(g, .18, TOP - Y + .5, .2, .04, M(P.wallLight),
        RX + Math.sin(a) * (RR + .04), Y + (TOP - Y + .5) / 2, RZ + Math.cos(a) * (RR + .04));
  }
  cyl(g, RR + .3, RR + .3, .26, 26, M(P.trim, .5), RX, Y + TOP - Y + .62, RZ);
  cyl(g, RR + .16, RR + .34, .22, 26, M(P.trim, .5), RX, Y + .06, RZ);
  /* 돔이 지붕에서 **솟아 있다**는 것을 목테 하나로 말합니다. 없으면
     반구가 지붕에 얹힌 게 아니라 파묻힌 것처럼 보입니다. */
  cyl(g, RR + .26, RR + .30, .30, 26, M(P.trim, .5), RX, TOP + .62, RZ);
  { const cap = new THREE.Mesh(new THREE.SphereGeometry(RR + .2, 24, 12, 0, Math.PI * 2, 0, Math.PI / 2),
                               M(P.roof, .35));
    cap.position.set(RX, TOP + .75, RZ); cap.scale.y = .5; cap.castShadow = true; g.add(cap); }

  /* 왼쪽으로 치우친 간판이 현관 캐노피 뒤에 묻혔습니다. 정면 중앙·위쪽으로
     옮기고 벽보다 더 앞으로 빼 어느 접근 각도에서도 읽히게 합니다. */
  /* 폭 4.8 은 캠퍼스 배율 2.2 를 곱하면 **월드 10.6** 입니다. 문 앞에
     서면 1280 폭 화면을 넘어가서 글자가 잘렸습니다. 미니게임관 간판
     (월드 6.5)과 같은 급으로 내립니다. */
  sign(g, '학생회관', 0, Y + G + 1.10, (D - .8) / 2 + .72, 3.4, .76, '#43A05C', '#FFFFFF');
}

/* ─────────────────────────────────────────────
   ⑤ 미니게임관/* ─────────────────────────────────────────────
   ⑤ 미니게임관 — 노는 집. 둥근 창 · 전구 간판 · 지붕 위 주사위
   ───────────────────────────────────────────── */
export function arcade(g, opt = {}) {
  /* 보라 채도를 낮춥니다. 원래 값은 여섯 채 중 혼자 튀어서, 캠퍼스를
     넓게 잡으면 게임관만 다른 그림에서 온 것처럼 보였습니다. */
  const P = C({ wall: 0xF6F0FA, wallLight: 0xFFFFFF, roof: 0xA391CF, roofDark: 0x8271B0 });
  if (opt.plate !== false) {
    plate(g, P, 14.4);
    [[-5.4, 4.4, .9], [5.4, 4.4, .9], [-5.6, -4.0, 1.05], [5.6, -4.0, 1.05]]
      .forEach(([x, z, s]) => tree(g, P, x, z, s));
  }
  const W = 8.4, D = 5.6, H1 = 3.4, Y = .12;
  box(g, W, H1, D, .14, M(P.wall), 0, Y + H1 / 2, 0);
  box(g, W + .3, .42, D + .3, .1, M(P.trim), 0, Y + H1 + .14, 0);
  /* 둥근 창 — 여섯 중 여기만 동그랗습니다.
     뒷면에는 아무것도 없었습니다. 캐릭터가 뒤로 돌면 보라색 빈 벽 하나가
     화면을 채웁니다. 뒤에는 **큰 창 하나**를 답니다 — 여러 개를 흩는 것보다
     하나가 크게 뚫린 편이 "안이 한 덩어리 게임장" 으로 읽힙니다. */
  [-2.9, -1.1, 1.1, 2.9].forEach((x) => {
    if (Math.abs(x) > 1.5) win(g, P, x, Y + H1 * .62, D / 2 + .02, 0, 1.3, 1.3, 'round');
  });
  [-1.5, 1.5].forEach((z) => {
    win(g, P, W / 2 + .02, Y + H1 * .62, z, Math.PI / 2, 1.3, 1.3, 'round');
    win(g, P, -W / 2 - .02, Y + H1 * .62, z, -Math.PI / 2, 1.3, 1.3, 'round');
  });
  win(g, P, 0, Y + H1 * .60, -D / 2 - .02, Math.PI, 2.6, 1.7, 'round');
  /* 뒷문 — 게임장에도 드나드는 문이 있습니다. 앞문보다 작고 장식이 없습니다 */
  door(g, P, -2.6, Y + 1.05, -D / 2 - .12, 1.3, 2.0);
  /* 뒤에 쌓인 오락기 상자 둘 — 뒤는 정리 안 된 곳이라는 게 오히려 사실적입니다 */
  [[-.6, .95, .8], [.55, .7, .62]].forEach(([x, h, w]) => {
    box(g, w, h, .7, .06, M(0x6E58A7, .6), x, Y + h / 2, -D / 2 - .55);
    box(g, w - .16, .34, .06, .03, M(0x9FE6F0, .35,
      { emissive: 0x5FCBDA, emissiveIntensity: .35 }), x, Y + h - .28, -D / 2 - .92);
  });
  /* 문과 아치를 한 단 줄입니다.
     미니게임관만 **단층**(H1 3.4)인데 다른 채와 같은 규격의 아치를 썼습니다.
     archPortal 은 문 위에서 솟고 반지름이 폭/2+0.72 이라, 2.4×2.5 짜리면
     꼭대기가 4.71 까지 올라갑니다 — 지붕 슬래브 위(4.13)를 넘어서, 뒤에서
     보면 지붕 너머로 흰 고리가 삐져나옵니다.
     1.9×2.0 으로 줄이면 꼭대기가 3.91 이라 지붕 안에 들어갑니다. */
  door(g, P, 0, Y + 1.0, D / 2 + .12, 1.9, 2.0);
  archPortal(g, P, 0, Y + 1.0 - (2.0) / 2, D / 2 + .12, 1.9, 2.0);
  apron(g, P, 0, 0, D / 2 + 1.05, 4.2);
  /* 전구를 두른 간판 — 밤에 여기만 눈에 띕니다.

     아치를 줄이면서 간판이 아치를 **뚫었습니다.** 간판은 y 2.45~3.59 에
     x ±2.10 까지 뻗는데, 그 높이에서 아치 링이 x ±1.10~±1.48 을 차지합니다.
     둘이 같은 자리를 두고 싸워서 전구가 아치 위에 박힌 것처럼 보였습니다.

     간판을 아치 **안쪽**으로 넣습니다 — 문 위 채광창 자리입니다. 아치 안
     반지름이 1.35 이므로 그 높이에서 폭 2.2 까지 들어갑니다. 좁아진 만큼
     아치가 간판의 테두리 노릇을 해서 오히려 한 덩어리로 읽힙니다. */
  const SG_Y = 2.62, SG_W = 2.15, SG_H = .78;
  /* 판은 어두운 남색, 글자는 네온 청록 — 파사드 띠와 같은 말을 합니다 */
  const sg = sign(g, '미니게임', 0, SG_Y, D / 2 + .30, SG_W, SG_H, '#241B3E', '#9FF6FA');
  /* 전구 대신 **네온 테** — 판을 청록 선 하나가 두릅니다. 전구알 열둘은
     "축제" 였고, 이어진 관 하나가 "아케이드" 입니다. 덜 화려하고 더 게임장. */
  const nf = (w2, h2, dx, dy) => {
    const n = box(sg, w2, h2, .06, .02,
      M(0x8FF3F7, .3, { emissive: 0x3FD6E8, emissiveIntensity: 1.0 }), dx, dy, .16);
    n.castShadow = false;
  };
  nf(SG_W + .16, .05, 0, SG_H / 2 + .10); nf(SG_W + .16, .05, 0, -SG_H / 2 - .10);
  nf(.05, SG_H + .26, SG_W / 2 + .105, 0); nf(.05, SG_H + .26, -SG_W / 2 - .105, 0);
  const yT = Y + H1 + .36;
  box(g, W + .5, .5, D + .5, .12, M(P.roof), 0, yT, 0);
  box(g, W - .1, .34, D - .1, .1, M(P.roofDark, .7), 0, yT + .3, 0);
  /* 지붕 위 타워를 낮춥니다.
     본체 높이가 3.4 인데 그 위에 1.9 짜리 덩어리 + 주사위 + 조이스틱이
     얹혀 있었습니다. 네 각도로 돌려 보면 지붕이 본체보다 커 보여서
     건물이 짓눌립니다. 타워를 1.9 → 1.05 로 낮추고 폭도 줄여, 지붕은
     받침이고 주사위가 주인공이 되게 합니다.

     티켓 띠와 토큰은 여기서 내려 **입구 옆 벽**으로 옮겼습니다(아래) —
     사람 눈높이에 있어야 읽히고, 지붕 위는 실루엣만 남습니다. */
  box(g, 4.6, 1.05, 3.4, .14, M(0xEEE8F8, .55), 0, yT + .78, -.25);
  box(g, 4.85, .22, 3.65, .07, M(0x6E58A7, .56), 0, yT + 1.36, -.25);
  /* ── 네온 파사드 띠 ──
     레퍼런스의 아케이드는 벽 전체가 아니라 **어두운 띠 위에서만** 네온이
     삽니다. 벽을 통째로 어둡게 하면 낮 캠퍼스에서 혼자 밤이 되므로,
     창 위~처마 아래의 빈 띠(2.88~3.45) 하나만 남보라로 어둡게 하고 그
     위에 네온 두 줄을 눕힙니다 — 화려함은 선 두 개로 충분합니다.
     (원래 이 자리에 있던 줄무늬 차양 둘은 뺐습니다 — 네온 띠와 겹치면
     정면이 도로 시끄러워집니다.) */
  box(g, W + .12, .52, .2, .06, M(0x3A3156, .62), 0, 3.18, D / 2 + .06);
  const NEON = (c, e) => M(c, .3, { emissive: e, emissiveIntensity: 1.0 });
  box(g, W - .7, .07, .07, .02, NEON(0x8FF3F7, 0x3FD6E8), 0, 3.30, D / 2 + .18)
    .castShadow = false;
  box(g, W - 1.9, .06, .06, .02, NEON(0xFFB3D9, 0xF25CA8), 0, 3.06, D / 2 + .18)
    .castShadow = false;
  /* 정면 둥근 창에는 청록 네온 링 — 게임장의 창은 밖으로도 빛납니다 */
  [-2.9, 2.9].forEach((x) => {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(.74, .045, 8, 30),
      NEON(0x8FF3F7, 0x3FD6E8));
    ring.position.set(x, Y + H1 * .62, D / 2 + .09);
    ring.castShadow = false; g.add(ring);
  });
  /* 티켓 띠와 토큰 — 지붕에서 내려 사람 눈높이로. 지붕 위에서는 위에서
     내려다보는 각도에만 보였습니다.

     처음엔 문 위(x 0 기준 폭 3.0)에 놓았는데, 문이 x ±0.95 이고 아치 기둥이
     ±1.35~1.67 이라 띠와 토큰이 문짝에 그대로 박혔습니다.

     그 다음 문 옆 빈 벽에 세로로 셋을 쌓았더니 **신호등**이 됐습니다 —
     빨강·파랑·흰색이 세로로 놓이면 사람은 먼저 신호등으로 읽습니다.
     가로로 눕혀 둥근 창 아래 띠로 붙입니다. */
  [-1, 1].forEach((sx) => {
    const bx = sx * 2.9;                       // 둥근 창 바로 아래
    box(g, 1.5, .20, .12, .05, M(0xFFD46F, .48), bx, Y + 1.16, D / 2 + .06);
    [-.42, 0, .42].forEach((dx, k) => {
      const token = new THREE.Mesh(new THREE.CylinderGeometry(.15, .15, .09, 14),
        M([0xF47A6A, 0x6FC6D9, 0xF9F4E6][k], .45));
      token.rotation.x = Math.PI / 2;
      token.position.set(bx + dx, Y + 1.16, D / 2 + .14);
      token.castShadow = true; g.add(token);
    });
  });

  /* 지붕 위 주사위 — 각진 것 하나. 나머지 다섯은 둥근 것을 이고 있습니다.
     타워를 낮췄으므로 주사위도 조금 줄이고 가운데로 옮깁니다 — 실루엣의
     꼭짓점이 하나여야 멀리서 "저기가 게임관" 으로 읽힙니다. */
  {
    /* 한 변 2.0 은 받침(폭 4.6, 높이 1.05)보다 키가 크고 폭의 43% 라,
       지붕에 얹힌 표식이 아니라 지붕을 덮은 짐짝으로 보였습니다.
       1.44 로 줄이면 실루엣의 꼭짓점 노릇은 그대로 하면서 건물이 삽니다. */
    const s = .72, ink = M(0x2A2036, .5);
    const cube = box(g, s * 2, s * 2, s * 2, .19, M(0xF9F4E6, .5), .2, yT + 1.36 + s, -.25);
    cube.rotation.y = .5;
    const R = s * .19;
    const pip = (dx, dy, dz, col) => {
      const m = new THREE.Mesh(new THREE.SphereGeometry(R, 12, 10), col);
      m.position.set(dx, dy, dz); cube.add(m);
    };
    /* 보이는 세 면은 5 · 3 · 6 입니다. 전 판은 5 · 2 · 3 이었는데
       주사위는 마주 보는 면의 합이 7 이라 **2 와 5 는 같이 못 보입니다.**
       가까이서 한 번 보면 가짜인 게 티가 나는 자리입니다. */
    const q = s * .5;
    [[-q, s + .02, -q], [q, s + .02, q], [0, s + .02, 0], [-q, s + .02, q], [q, s + .02, -q]]
      .forEach(([a, b, c2], i) => pip(a, b, c2, i === 2 ? M(0xD8442C, .45) : ink));
    [-q, 0, q].forEach((dy) => [-q, q].forEach((dx) => pip(dx, dy, s + .02, ink)));
    [[s + .02, q, 0], [s + .02, -q, 0], [s + .02, 0, 0]].forEach(([a, b, c2]) => pip(a, b, c2, ink));
  }
  /* 조이스틱은 **뺐습니다.**

     원래 지붕 위에 있었고, 실루엣의 꼭짓점이 주사위와 둘이 되어 무엇이
     주인공인지 흐려져서 땅으로 내렸습니다. 그런데 정면에 놓을 자리가
     없습니다 — 문(아치 바깥 ±1.67)과 둥근 창(±2.25~3.55) 사이의 빈 구간이
     0.58 뿐이라 받침(0.9)이 애초에 안 들어갑니다. 어디에 놓아도 문이나
     창과 겹칩니다.

     그리고 정면에는 이미 주사위·간판·전구·티켓 띠·토큰·차양이 있습니다.
     하나를 더 놓는 것이 아니라 하나를 빼는 것이 맞습니다 — 겹쳐서 시끄러운
     것이 문제였지 게임관으로 안 읽히는 것이 문제가 아니었습니다. */
}

/* ─────────────────────────────────────────────
   ⑥ 동아리 상점 — 장사하는 집. 줄무늬 차양 · 진열창 · 매대
   ───────────────────────────────────────────── */
export function shop(g, opt = {}) {
  /* 지붕 빨강을 벽돌 쪽으로 한 단 눕힙니다. 원래 값은 본관 국기와 같은
     채도라 월드에 나란히 놓으면 두 원색이 싸웠습니다. */
  const P = C({ wall: 0xFFEFE2, wallLight: 0xFFF8F0, roof: 0xCE6A52, roofDark: 0xA8482F });
  if (opt.plate !== false) {
    plate(g, P, 14.0);
    [[-5.2, 4.2, .9], [5.2, 4.2, .9], [-5.4, -3.8, 1.0], [5.4, -3.8, 1.0]]
      .forEach(([x, z, s]) => tree(g, P, x, z, s));
  }
  const W = 8.0, D = 5.2, H1 = 3.1, Y = .12;
  box(g, W, H1, D, .14, M(P.wall), 0, Y + H1 / 2, 0);
  /* 벽돌 띠 — 장사하는 집이라 결이 따뜻해야 합니다 */
  for (let i = 0; i < 4; i++)
    box(g, W + .04, .1, D + .04, .04, M(0xE2C4AE, .8), 0, Y + .5 + i * .34, 0);
  box(g, W + .3, .42, D + .3, .1, M(P.trim), 0, Y + H1 + .14, 0);
  /* 진열창 둘 — 크고 낮습니다. 물건이 보여야 하니까요 */
  [-2.5, 2.5].forEach((x) => win(g, P, x, Y + H1 * .5, D / 2 + .02, 0, 2.0, 2.0));
  /* ── 쇼윈도를 **가게의 창**으로 ──
     레퍼런스의 상점은 창이 셋 다 말을 합니다: 나무 틀 · 안의 따뜻한 불 ·
     창턱의 물건. 유리만 있으면 사무실 창과 구분이 안 됩니다. */
  [-2.5, 2.5].forEach((x, i) => {
    /* 나무 틀 — 위·좌우 세 짝. (아래는 창턱 선반이 대신합니다) */
    box(g, 2.24, .13, .16, .04, M(0xC97F5B, .6), x, Y + H1 * .5 + 1.06, D / 2 + .07);
    [-1, 1].forEach((s) =>
      box(g, .13, 2.24, .16, .04, M(0xC97F5B, .6), x + s * 1.06, Y + H1 * .5, D / 2 + .07));
    /* 안의 불 — 기숙사 불 켜진 창과 같은 문법의 따뜻한 색. "열려 있다" 는 말 */
    box(g, 1.84, 1.7, .04, .02, M(0xFFDFA0, .32,
      { emissive: 0xFFC65C, emissiveIntensity: .55 }), x, Y + H1 * .5 + .06, D / 2 + .045)
      .castShadow = false;
    /* 창턱 선반과 물건 셋 — 선물상자 · 병 · 인형. 실루엣이 불빛을 등집니다 */
    box(g, 2.1, .14, .34, .05, M(0xC49A6C, .7), x, Y + .74, D / 2 + .16);
    box(g, .34, .3, .26, .04, M(i ? 0x6FC6D9 : 0xF47A6A, .6), x - .6, Y + .96, D / 2 + .16);
    box(g, .38, .1, .28, .03, M(0xF2B33C, .55), x - .6, Y + 1.16, D / 2 + .16);
    cyl(g, .11, .13, .4, 10, M(0x5C9E63, .35), x + .02, Y + 1.01, D / 2 + .16);
    { const b = new THREE.Mesh(new THREE.SphereGeometry(.17, 12, 10),
        M(i ? 0xF2B6C6 : 0xFFE7A8, .6));
      b.position.set(x + .62, Y + .98, D / 2 + .16); b.castShadow = true; g.add(b); }
  });
  [-1.3, 1.3].forEach((z) => {
    win(g, P, W / 2 + .02, Y + H1 * .55, z, Math.PI / 2, 1.5, 1.7);
    win(g, P, -W / 2 - .02, Y + H1 * .55, z, -Math.PI / 2, 1.5, 1.7);
  });
  /* 아치가 지붕을 넘던 것을 줄입니다.
     2.0×2.4 면 꼭대기가 4.41 인데 1층 지붕 슬래브 위가 3.83 입니다 —
     0.58 만큼 삐져나와, 뒤에서 보면 2층 벽 옆으로 흰 고리가 떠 있습니다.
     1.7×2.0 으로 줄이면 3.99 … 아직 넘으므로 아치를 빼고 문틀만 둡니다.
     차양이 이미 가게의 표시라서, 아치까지 있으면 정면이 시끄럽기도 합니다. */
  door(g, P, 0, Y + 1.15, D / 2 + .12, 2.0, 2.2);
  /* reveal 의 y 는 문 **바닥**입니다(안에서 y-.2 부터 쌓습니다). */
  reveal(g, P, 0, Y + .2, D / 2 + .02, 2.0, 2.2, .26);
  /* 문 옆 벽등 둘 — 따뜻한 알 하나씩. 레퍼런스의 가게 문은 늘 밝습니다 */
  [-1, 1].forEach((s) => {
    box(g, .1, .26, .16, .03, M(0x6B4A2A, .55), s * 1.42, Y + 2.16, D / 2 + .10);
    const b = new THREE.Mesh(new THREE.SphereGeometry(.1, 10, 8),
      M(0xFFE2A4, .3, { emissive: 0xFFC65C, emissiveIntensity: .8 }));
    b.position.set(s * 1.42, Y + 2.02, D / 2 + .16); b.castShadow = false; g.add(b);
  });
  apron(g, P, 0, 0, D / 2 + 1.0, 4.2);
  /* ── 행잉 간판 ──
     벽 모서리에서 나온 쇠막대에 작은 원판이 매달립니다. 정면 간판이
     "지나가는 사람"에게 말한다면 이것은 **길을 따라 걸어오는 사람**에게
     말하는 간판입니다 — 레퍼런스의 가게가 전부 이것을 답니다.
     차양(x 1.3~3.7, z ~4.2까지)을 피해 모서리(x 3.85) 위쪽에 겁니다. */
  {
    const hx = 3.85, hy = Y + H1 - .1;
    const arm = cyl(g, .045, .045, 1.1, 8, M(0x6B4A2A, .5), hx, hy, D / 2 + .55);
    arm.rotation.x = Math.PI / 2;
    cyl(g, .032, .032, .4, 8, M(0x6B4A2A, .5), hx, hy - .2, D / 2 + .95);
    const disc = cyl(g, .44, .44, .1, 22, M(0xFFF3DC, .5), hx, hy - .84, D / 2 + .95);
    disc.rotation.x = Math.PI / 2;
    const rim = cyl(g, .48, .48, .05, 22, M(0xC4553F, .5), hx, hy - .84, D / 2 + .93);
    rim.rotation.x = Math.PI / 2;
    /* 원판 위 동전 하나 — 파는 집이라는 말을 그림 하나로 */
    const dot = new THREE.Mesh(new THREE.SphereGeometry(.15, 12, 10), M(0xF2B33C, .45));
    dot.position.set(hx, hy - .84, D / 2 + 1.02); dot.castShadow = true; g.add(dot);
  }
  /* 줄무늬 차양 — 가게의 표시 */
  [-2.5, 0, 2.5].forEach((x) => {
    const wdt = x === 0 ? 2.6 : 2.4;
    for (let i = 0; i < 6; i++) {
      const sw = wdt / 6;
      const st = box(g, sw, .16, 1.5, .06, M(i % 2 ? 0xE8483C : 0xFFF6E6, .62),
                     x - wdt / 2 + sw * (i + .5), Y + H1 - .32, D / 2 + .82);
      st.rotation.x = -.24;
    }
    box(g, wdt + .1, .2, .24, .06, M(P.roofDark, .6), x, Y + H1 - .62, D / 2 + 1.52);
  });
  /* 매대 — 문 옆 상자 셋 */
  /* 깊이 1.0짜리 상자를 .9 간격으로 두면 0.1만큼 서로 파고들어,
     비스듬히 볼 때 건물 정면과 매대가 깨진 한 덩어리처럼 보였습니다.
     두 번째 상자를 1.14 뒤로 보내 얇은 통로색 틈을 남깁니다. */
  [[-3.2, .0], [-3.2, 1.14]].forEach(([x, dz], i) => {
    box(g, 1.3, .7, 1.0, .08, M(0xC08E58, .75), x, Y + .45, D / 2 + 1.0 + dz);
    [0xE8483C, 0xF2B33C, 0x63C47C].forEach((col, k) => {
      const b = new THREE.Mesh(new THREE.SphereGeometry(.19, 14, 12), M(col, .55));
      b.position.set(x - .35 + k * .35, Y + .92, D / 2 + 1.0 + dz);
      b.castShadow = true; g.add(b);
    });
  });
  const yT = Y + H1 + .36;
  box(g, W + .5, .5, D + .5, .12, M(P.roof), 0, yT, 0);
  /* 단층 창고처럼 보이던 외곽을 작은 거리형 2층 숍으로 올립니다.
     2층이 1층과 성격이 같으면 "상점 위가 뭔지" 를 화면이 말하지 못합니다.
     여기는 **주인이 사는 층**입니다 — 창턱 화분과 널어 둔 천 하나로 그
     말을 합니다. 뒤에도 창을 내어 앞뒤가 같은 집이 되게 합니다. */
  box(g, 6.5, 2.0, 4.25, .16, M(0xFFF7EE, .53), 0, yT + 1.15, -.18);
  [-1.85, 0, 1.85].forEach((x) => win(g, P, x, yT + 1.2, 1.97, 0, 1.25, 1.05));
  [-1.6, 1.6].forEach((x) => win(g, P, x, yT + 1.2, -2.33, Math.PI, 1.1, 1.0));
  /* 창턱 화분 둘 — 사는 층이라는 표시.
     창(z 1.97) 바로 앞 z 2.10 에 두었더니 아래 차양(z 2.42 까지)에 가려
     정면에서 안 보였습니다. 창턱 위로 올리고 앞으로 조금 더 냅니다. */
  [-1.85, 1.85].forEach((x, i) => {
    box(g, .66, .24, .32, .05, M(0xC97F5B, .7), x, yT + .70, 2.22);
    const leaf = new THREE.Mesh(new THREE.SphereGeometry(.20, 10, 8),
      M(i ? 0x6BB86F : 0x84C873, .62));
    leaf.position.set(x, yT + .92, 2.22); leaf.scale.set(1.35, .95, 1);
    leaf.castShadow = true; g.add(leaf);
  });
  /* 널어 둔 천 한 장 — 가운데 창 옆에서 늘어집니다 */
  const cloth = box(g, .46, .74, .03, .02, M(0xEFD9A8, .88), .78, yT + .92, 2.20);
  cloth.rotation.z = .06;
  box(g, 6.8, .22, 4.5, .08, M(P.roofDark, .58), 0, yT + 2.17, -.18);
  prism(g, 7.15, 1.45, 4.65, M(P.roof, .6), 0, yT + 2.24, -.18);
  /* 쇼윈도 아래 화분 진열 — 문 앞 중앙 통로는 비웁니다. */
  [-3.25, -2.45, 2.45, 3.25].forEach((x, i) => {
    cyl(g, .23, .18, .36, 12, M(i % 2 ? 0xD77A55 : 0xE5A565, .55), x, .30, D / 2 + .42);
    const leaf = new THREE.Mesh(new THREE.SphereGeometry(.27, 12, 9), M(i % 2 ? 0x65B96B : 0x84C873, .6));
    leaf.position.set(x, .62, D / 2 + .42); leaf.scale.set(1, 1.25, 1); leaf.castShadow = true; g.add(leaf);
  });

  /* ── 뒷마당 ──────────────────────────────────────────────
     앞은 가게고 뒤는 창고입니다. 그런데 뒤가 그냥 빈 벽이라, 캐릭터가
     돌아가면 앞의 이야기가 뚝 끊겼습니다.

     가게의 뒤는 **정리되지 않은 곳**입니다. 그게 사실이고, 사실이라서
     앞의 진열이 더 진열처럼 보입니다 — 뒤도 예쁘면 둘 다 무대가 됩니다. */
  /* 뒷문 — 앞문보다 작고 아치가 없습니다 */
  door(g, P, -2.2, Y + 1.0, -D / 2 - .12, 1.4, 2.0);
  /* 쌓아 둔 궤짝 — 높이를 어긋나게 둡니다. 나란하면 진열이 됩니다 */
  [[.9, .0, .62], [.9, .62, .62], [2.1, .0, .70]].forEach(([x, dy, s]) => {
    box(g, s * 1.5, s, s * 1.2, .05, M(0xC08E58, .78), x, Y + dy + s / 2, -D / 2 - .62);
    box(g, s * 1.55, .06, s * 1.25, .02, M(0xA97443, .8), x, Y + dy + s, -D / 2 - .62);
  });
  /* 빈 병 상자 하나 — 초록 유리가 궤짝의 나무색과 갈립니다 */
  box(g, .9, .34, .62, .04, M(0x8A6440, .8), -.5, Y + .17, -D / 2 - .70);
  [-.78, -.5, -.22].forEach((x) =>
    cyl(g, .09, .09, .34, 8, M(0x5C9E63, .35), x, Y + .5, -D / 2 - .70));
  /* 접힌 차양 천 한 뭉치 — 앞의 줄무늬가 여기 여분으로 있습니다 */
  const roll = cyl(g, .22, .22, 1.5, 10, M(0xE8483C, .7), 3.0, Y + .24, -D / 2 - .55);
  roll.rotation.z = Math.PI / 2;
  /* 뒷벽 창 둘 — 창고에도 빛은 듭니다. 앞 진열창보다 작고 높습니다 */
  [-3.0, 3.0].forEach((x) => win(g, P, x, Y + H1 * .66, -D / 2 - .02, Math.PI, 1.0, .95));

  /* ── 옆면 매대 ──
     상점인데 물건이 앞 왼쪽 한 자리에만 있었습니다. 옆에도 하나 두어
     "돌아가도 계속 가게" 가 되게 합니다. 앞 매대와 같은 부품, 다른 물건. */
  {
    const sx = W / 2 + .95;
    box(g, 1.0, .7, 1.6, .08, M(0xC08E58, .75), sx, Y + .45, .2);
    [0xF2B33C, 0x63C47C].forEach((col, k) => {
      const b = new THREE.Mesh(new THREE.SphereGeometry(.18, 14, 12), M(col, .55));
      b.position.set(sx, Y + .92, -.2 + k * .8); b.castShadow = true; g.add(b);
    });
    /* 값 적는 작은 칠판 */
    const bd = box(g, .06, .55, .8, .03, M(0x3B4A42, .7), sx - .52, Y + 1.05, .2);
    bd.rotation.z = .08;
  }
  /* 지붕 위 간판 */
  /* 간판이 z = .1, 즉 건물 **한가운데**에 박혀 있어 벽에 가려 안
     보였습니다. 미니게임관처럼 정면 벽 바깥(z = D/2 + 조금)으로 냅니다.
     이 건물의 정면 깊이는 D 이므로 그 절반에 여유를 더합니다. */
  /* 간판 꼭대기가 박공 지붕을 0.2 넘어, 뒤에서 보면 지붕 위로 회색 판이
     떠 있었습니다. 처마 선에 맞춰 내립니다 — 가게 간판이 원래 있는 자리입니다. */
  sign(g, '동아리 상점', 0, yT + 2.05, D / 2 + .42, 5.2, 1.25, '#C4553F', '#FFF3DC');
  /* 간판 받침 — 벽에서 조금 띄워 그늘 한 줄 */
  box(g, 5.6, .2, .5, .05, M(P.trim, .5), 0, yT + 1.82, D / 2 + .34);
  [-1.6, 1.6].forEach((x) => box(g, .16, 1.0, .16, .05, M(P.roofDark, .6), x, yT + 2.35, D / 2 + .18));
}

/* ─────────────────────────────────────────────
   그리기
   ───────────────────────────────────────────── */
export const BLD = { mainHall, library, dorm, union, arcade, shop };
